    J[2] -= dqdci; // dwdot[O]/d[H2]
    J[4] += dqdci; // dwdot[OH]/d[H2]
    // d()/d[H]
    dqdci = +k_f * sc[2];
    J[19] -= dqdci; // dwdot[H]/d[H]
    J[20] -= dqdci; // dwdot[O]/d[H]
    J[22] += dqdci; // dwdot[OH]/d[H]
    // d()/d[O]
    dqdci = +k_f * sc[1];
