    J[38] -= dqdci; // dwdot[O]/d[O]
    J[40] += dqdci; // dwdot[OH]/d[O]
    // d()/d[OH]
    dqdci = -k_r;
    J[73] -= dqdci; // dwdot[H]/d[OH]
    J[74] -= dqdci; // dwdot[O]/d[OH]
    J[76] += dqdci; // dwdot[OH]/d[OH]
    // d()/d[H2O]
    dqdci = (6 - 1) * q_nocor;
    J[91] -= dqdci; // dwdot[H]/d[H2O]
    J[92] -= dqdci; // dwdot[O]/d[H2O]
    J[94] += dqdci; // dwdot[OH]/d[H2O]
    // d()/d[CH4]
    dqdci = (2 - 1) * q_nocor;
    J[181] -= dqdci; // dwdot[H]/d[CH4]
    J[182] -= dqdci; // dwdot[O]/d[CH4]
    J[184] += dqdci; // dwdot[OH]/d[CH4]
    // d()/d[CO]
    dqdci = (1.5 - 1) * q_nocor;
    J[199] -= dqdci; // dwdot[H]/d[CO]
    J[200] -= dqdci; // dwdot[O]/d[CO]
    J[202] += dqdci; // dwdot[OH]/d[CO]
