  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(h_RT[1] + h_RT[3] + h_RT[16]) + (h_RT[6] + h_RT[16]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[1] -= q; // H
  wdot[3] -= q; // O2
  wdot[6] += q; // HO2
  // d()/d[H]
  dqdci = +k_f * sc[3] * sc[16];
  J[19] -= dqdci; // dwdot[H]/d[H]
  J[21] -= dqdci; // dwdot[O2]/d[H]
  J[24] += dqdci; // dwdot[HO2]/d[H]
  // d()/d[O2]
  dqdci = +k_f * sc[1] * sc[16];
  J[55] -= dqdci; // dwdot[H]/d[O2]
  J[57] -= dqdci; // dwdot[O2]/d[O2]
  J[60] += dqdci; // dwdot[HO2]/d[O2]
  // d()/d[HO2]
  dqdci = -k_r * sc[16];
  J[109] -= dqdci; // dwdot[H]/d[HO2]
  J[111] -= dqdci; // dwdot[O2]/d[HO2]
  J[114] += dqdci; // dwdot[HO2]/d[HO2]
  // d()/d[N2]
  dqdci = +k_f * sc[1] * sc[3] - k_r * sc[6];
  J[289] -= dqdci; // dwdot[H]/d[N2]
  J[291] -= dqdci; // dwdot[O2]/d[N2]
  J[294] += dqdci; // dwdot[HO2]/d[N2]
  // d()/dT
  J[307] -= dqdT; // dwdot[H]/dT
  J[309] -= dqdT; // dwdot[O2]/dT
  J[312] += dqdT; // dwdot[HO2]/dT

  // reaction 20: 2 H + M <=> H2 + M
  // a third-body and non-pressure-fall-off reaction
  // 3-body correction factor
  alpha =
    mixture + (0 - 1) * sc[0] + (0 - 1) * sc[5] + sc[10] + (0 - 1) * sc[12];
  // forward
  phi_f = (sc[1] * sc[1]);
  k_f = 1000000 * exp(-1 * logT);
  dlnkfdT = -1 * invT;
  // reverse
  phi_r = sc[0];
  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(2.000000 * h_RT[1]) + (h_RT[0]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q_nocor = k_f * phi_f - k_r * phi_r;
  q = alpha * q_nocor;
  dqdT = alpha * (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[0] += q;     // H2
  wdot[1] -= 2 * q; // H
  // for convenience
  k_f *= alpha;
  k_r *= alpha;
  if (consP == 1) {
    // d()/d[H2]
    dqdci = (0 - 1) * q_nocor - k_r;
    J[0] += dqdci;      // dwdot[H2]/d[H2]
    J[1] += -2 * dqdci; // dwdot[H]/d[H2]
    // d()/d[H]
    dqdci = +k_f * 2.000000 * sc[1];
    J[18] += dqdci;      // dwdot[H2]/d[H]
    J[19] += -2 * dqdci; // dwdot[H]/d[H]
    // d()/d[H2O]
    dqdci = (0 - 1) * q_nocor;
    J[90] += dqdci;      // dwdot[H2]/d[H2O]
    J[91] += -2 * dqdci; // dwdot[H]/d[H2O]
    // d()/d[CH4]
    dqdci = (2 - 1) * q_nocor;
    J[180] += dqdci;      // dwdot[H2]/d[CH4]
    J[181] += -2 * dqdci; // dwdot[H]/d[CH4]
    // d()/d[CO2]
    dqdci = (0 - 1) * q_nocor;
    J[216] += dqdci;      // dwdot[H2]/d[CO2]
    J[217] += -2 * dqdci; // dwdot[H]/d[CO2]
  } else {
    dqdc[0] = -k_r;
    dqdc[1] = q_nocor + k_f * 2.000000 * sc[1];
    dqdc[2] = q_nocor;
    dqdc[3] = q_nocor;
    dqdc[4] = q_nocor;
    dqdc[6] = q_nocor;
    dqdc[7] = q_nocor;
    dqdc[8] = q_nocor;
    dqdc[9] = q_nocor;
    dqdc[10] = 2 * q_nocor;
    dqdc[11] = q_nocor;
    dqdc[13] = q_nocor;
    dqdc[14] = q_nocor;
    dqdc[15] = q_nocor;
    dqdc[16] = q_nocor;
    for (int k = 0; k < 17; k++) {
      J[18 * k + 0] += dqdc[k];
      J[18 * k + 1] += -2 * dqdc[k];
    }
  }
  J[306] += dqdT;      // dwdot[H2]/dT
  J[307] += -2 * dqdT; // dwdot[H]/dT

  // reaction 21: 2 H + H2 <=> H2 + H2
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[0] * (sc[1] * sc[1]);
  k_f = 90000 * exp(-0.6 * logT);
  dlnkfdT = -0.6 * invT;
  // reverse
  phi_r = (sc[0] * sc[0]);
  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(h_RT[0] + 2.000000 * h_RT[1]) + (2.000000 * h_RT[0]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[0] += q;     // H2
  wdot[1] -= 2 * q; // H
  // d()/d[H2]
  dqdci = +k_f * sc[1] * sc[1] - k_r * 2.000000 * sc[0];
  J[0] += dqdci;      // dwdot[H2]/d[H2]
  J[1] += -2 * dqdci; // dwdot[H]/d[H2]
  // d()/d[H]
  dqdci = +k_f * sc[0] * 2.000000 * sc[1];
  J[18] += dqdci;      // dwdot[H2]/d[H]
  J[19] += -2 * dqdci; // dwdot[H]/d[H]
  // d()/dT
  J[306] += dqdT;      // dwdot[H2]/dT
  J[307] += -2 * dqdT; // dwdot[H]/dT

  // reaction 22: 2 H + H2O <=> H2 + H2O
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = (sc[1] * sc[1]) * sc[5];
  k_f = 60000000 * exp(-1.25 * logT);
  dlnkfdT = -1.25 * invT;
  // reverse
  phi_r = sc[0] * sc[5];
  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(2.000000 * h_RT[1] + h_RT[5]) + (h_RT[0] + h_RT[5]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[0] += q;     // H2
  wdot[1] -= 2 * q; // H
  // d()/d[H2]
  dqdci = -k_r * sc[5];
  J[0] += dqdci;      // dwdot[H2]/d[H2]
  J[1] += -2 * dqdci; // dwdot[H]/d[H2]
  // d()/d[H]
  dqdci = +k_f * 2.000000 * sc[1] * sc[5];
  J[18] += dqdci;      // dwdot[H2]/d[H]
  J[19] += -2 * dqdci; // dwdot[H]/d[H]
  // d()/d[H2O]
  dqdci = +k_f * sc[1] * sc[1] - k_r * sc[0];
  J[90] += dqdci;      // dwdot[H2]/d[H2O]
  J[91] += -2 * dqdci; // dwdot[H]/d[H2O]
  // d()/dT
  J[306] += dqdT;      // dwdot[H2]/dT
  J[307] += -2 * dqdT; // dwdot[H]/dT

  // reaction 23: 2 H + CO2 <=> H2 + CO2
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = (sc[1] * sc[1]) * sc[12];
  k_f = 550000000 * exp(-2 * logT);
  dlnkfdT = -2 * invT;
  // reverse
  phi_r = sc[0] * sc[12];
  Kc = refCinv * (kc_fast ? (ge[0] * inv_ge[1] * inv_ge[1])
                          : exp(-g_RT[0] + 2.000000 * g_RT[1]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(2.000000 * h_RT[1] + h_RT[12]) + (h_RT[0] + h_RT[12]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[0] += q;     // H2
  wdot[1] -= 2 * q; // H
  // d()/d[H2]
  dqdci = -k_r * sc[12];
  J[0] += dqdci;      // dwdot[H2]/d[H2]
  J[1] += -2 * dqdci; // dwdot[H]/d[H2]
  // d()/d[H]
  dqdci = +k_f * 2.000000 * sc[1] * sc[12];
  J[18] += dqdci;      // dwdot[H2]/d[H]
  J[19] += -2 * dqdci; // dwdot[H]/d[H]
  // d()/d[CO2]
  dqdci = +k_f * sc[1] * sc[1] - k_r * sc[0];
  J[216] += dqdci;      // dwdot[H2]/d[CO2]
  J[217] += -2 * dqdci; // dwdot[H]/d[CO2]
  // d()/dT
  J[306] += dqdT;      // dwdot[H2]/dT
  J[307] += -2 * dqdT; // dwdot[H]/dT

  // reaction 24: H + OH + M <=> H2O + M
  // a third-body and non-pressure-fall-off reaction
  // 3-body correction factor
  alpha = mixture + (0.73 - 1) * sc[0] + (3.65 - 1) * sc[5] + sc[10];
  // forward
  phi_f = sc[1] * sc[4];
  k_f = 22000000000 * exp(-2 * logT);
  dlnkfdT = -2 * invT;
  // reverse
  phi_r = sc[5];
  Kc = refCinv * (kc_fast ? (inv_ge[4] * inv_ge[1] * ge[5])
                          : exp(g_RT[1] + g_RT[4] - g_RT[5]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[1] + h_RT[4]) + (h_RT[5]) + 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q_nocor = k_f * phi_f - k_r * phi_r;
  q = alpha * q_nocor;
  dqdT = alpha * (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[1] -= q; // H
  wdot[4] -= q; // OH
  wdot[5] += q; // H2O
  // for convenience
  k_f *= alpha;
  k_r *= alpha;
  if (consP == 1) {
    // d()/d[H2]
    dqdci = (0.73 - 1) * q_nocor;
    J[1] -= dqdci; // dwdot[H]/d[H2]
    J[4] -= dqdci; // dwdot[OH]/d[H2]
    J[5] += dqdci; // dwdot[H2O]/d[H2]
    // d()/d[H]
    dqdci = +k_f * sc[4];
    J[19] -= dqdci; // dwdot[H]/d[H]
    J[22] -= dqdci; // dwdot[OH]/d[H]
    J[23] += dqdci; // dwdot[H2O]/d[H]
    // d()/d[OH]
    dqdci = +k_f * sc[1];
    J[73] -= dqdci; // dwdot[H]/d[OH]
    J[76] -= dqdci; // dwdot[OH]/d[OH]
    J[77] += dqdci; // dwdot[H2O]/d[OH]
    // d()/d[H2O]
    dqdci = (3.65 - 1) * q_nocor - k_r;
    J[91] -= dqdci; // dwdot[H]/d[H2O]
    J[94] -= dqdci; // dwdot[OH]/d[H2O]
    J[95] += dqdci; // dwdot[H2O]/d[H2O]
    // d()/d[CH4]
    dqdci = (2 - 1) * q_nocor;
    J[181] -= dqdci; // dwdot[H]/d[CH4]
    J[184] -= dqdci; // dwdot[OH]/d[CH4]
    J[185] += dqdci; // dwdot[H2O]/d[CH4]
  } else {
    dqdc[0] = 0.73 * q_nocor;
    dqdc[1] = q_nocor + k_f * sc[4];
    dqdc[2] = q_nocor;
    dqdc[3] = q_nocor;
    dqdc[4] = q_nocor + k_f * sc[1];
    dqdc[5] = 3.65 * q_nocor - k_r;
    dqdc[6] = q_nocor;
    dqdc[7] = q_nocor;
    dqdc[8] = q_nocor;
    dqdc[9] = q_nocor;
    dqdc[10] = 2 * q_nocor;
    dqdc[11] = q_nocor;
    dqdc[12] = q_nocor;
    dqdc[13] = q_nocor;
    dqdc[14] = q_nocor;
    dqdc[15] = q_nocor;
    dqdc[16] = q_nocor;
    for (int k = 0; k < 17; k++) {
      J[18 * k + 1] -= dqdc[k];
      J[18 * k + 4] -= dqdc[k];
      J[18 * k + 5] += dqdc[k];
    }
  }
  J[307] -= dqdT; // dwdot[H]/dT
  J[310] -= dqdT; // dwdot[OH]/dT
  J[311] += dqdT; // dwdot[H2O]/dT

  // reaction 69: HCO + H2O <=> CO + H + H2O
  // a third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[5] * sc[13];
  k_f = 2244000000000 * exp(-1 * logT - (8554.68331868023) * invT);
  dlnkfdT = -1 * invT + (8554.68331868023) * invT2;
  // reverse
  phi_r = sc[1] * sc[5] * sc[11];
  Kc = refC * (kc_fast ? (inv_ge[13] * ge[11] * ge[1])
                       : exp(-g_RT[1] - g_RT[11] + g_RT[13]));
  k_r = k_f / Kc;
  dlnKcdT =
    invT * (-(h_RT[5] + h_RT[13]) + (h_RT[1] + h_RT[5] + h_RT[11]) - 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[1] += q;  // H
  wdot[11] += q; // CO
  wdot[13] -= q; // HCO
  // d()/d[H]
  dqdci = -k_r * sc[5] * sc[11];
  J[19] += dqdci; // dwdot[H]/d[H]
  J[29] += dqdci; // dwdot[CO]/d[H]
  J[31] -= dqdci; // dwdot[HCO]/d[H]
  // d()/d[H2O]
  dqdci = +k_f * sc[13] - k_r * sc[1] * sc[11];
  J[91] += dqdci;  // dwdot[H]/d[H2O]
  J[101] += dqdci; // dwdot[CO]/d[H2O]
  J[103] -= dqdci; // dwdot[HCO]/d[H2O]
  // d()/d[CO]
  dqdci = -k_r * sc[1] * sc[5];
  J[199] += dqdci; // dwdot[H]/d[CO]
  J[209] += dqdci; // dwdot[CO]/d[CO]
  J[211] -= dqdci; // dwdot[HCO]/d[CO]
  // d()/d[HCO]
  dqdci = +k_f * sc[5];
  J[235] += dqdci; // dwdot[H]/d[HCO]
  J[245] += dqdci; // dwdot[CO]/d[HCO]
  J[247] -= dqdci; // dwdot[HCO]/d[HCO]
  // d()/dT
  J[307] += dqdT; // dwdot[H]/dT
  J[317] += dqdT; // dwdot[CO]/dT
  J[319] -= dqdT; // dwdot[HCO]/dT

  // reaction 70: HCO + M <=> CO + H + M
  // a third-body and non-pressure-fall-off reaction
  // 3-body correction factor
  alpha =
    mixture + sc[0] + (0 - 1) * sc[5] + sc[10] + (1.5 - 1) * sc[11] + sc[12];
  // forward
  phi_f = sc[13];
  k_f = 187000000000 * exp(-1 * logT - (8554.68331868023) * invT);
  dlnkfdT = -1 * invT + (8554.68331868023) * invT2;
  // reverse
  phi_r = sc[1] * sc[11];
  Kc = refC * (kc_fast ? (inv_ge[13] * ge[11] * ge[1])
                       : exp(-g_RT[1] - g_RT[11] + g_RT[13]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[13]) + (h_RT[1] + h_RT[11]) - 1.000000);
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q_nocor = k_f * phi_f - k_r * phi_r;
  q = alpha * q_nocor;
  dqdT = alpha * (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[1] += q;  // H
  wdot[11] += q; // CO
  wdot[13] -= q; // HCO
  // for convenience
  k_f *= alpha;
  k_r *= alpha;
  if (consP == 1) {
    // d()/d[H2]
    dqdci = (2 - 1) * q_nocor;
    J[1] += dqdci;  // dwdot[H]/d[H2]
    J[11] += dqdci; // dwdot[CO]/d[H2]
    J[13] -= dqdci; // dwdot[HCO]/d[H2]
    // d()/d[H]
    dqdci = -k_r * sc[11];
    J[19] += dqdci; // dwdot[H]/d[H]
    J[29] += dqdci; // dwdot[CO]/d[H]
    J[31] -= dqdci; // dwdot[HCO]/d[H]
    // d()/d[H2O]
    dqdci = (0 - 1) * q_nocor;
    J[91] += dqdci;  // dwdot[H]/d[H2O]
    J[101] += dqdci; // dwdot[CO]/d[H2O]
    J[103] -= dqdci; // dwdot[HCO]/d[H2O]
    // d()/d[CH4]
    dqdci = (2 - 1) * q_nocor;
    J[181] += dqdci; // dwdot[H]/d[CH4]
    J[191] += dqdci; // dwdot[CO]/d[CH4]
    J[193] -= dqdci; // dwdot[HCO]/d[CH4]
    // d()/d[CO]
    dqdci = (1.5 - 1) * q_nocor - k_r * sc[1];
    J[199] += dqdci; // dwdot[H]/d[CO]
    J[209] += dqdci; // dwdot[CO]/d[CO]
    J[211] -= dqdci; // dwdot[HCO]/d[CO]
    // d()/d[CO2]
    dqdci = (2 - 1) * q_nocor;
    J[217] += dqdci; // dwdot[H]/d[CO2]
    J[227] += dqdci; // dwdot[CO]/d[CO2]
    J[229] -= dqdci; // dwdot[HCO]/d[CO2]
    // d()/d[HCO]
    dqdci = +k_f;
    J[235] += dqdci; // dwdot[H]/d[HCO]
    J[245] += dqdci; // dwdot[CO]/d[HCO]
    J[247] -= dqdci; // dwdot[HCO]/d[HCO]
  } else {
    dqdc[0] = 2 * q_nocor;
    dqdc[1] = q_nocor - k_r * sc[11];
    dqdc[2] = q_nocor;
    dqdc[3] = q_nocor;
    dqdc[4] = q_nocor;
    dqdc[6] = q_nocor;
    dqdc[7] = q_nocor;
    dqdc[8] = q_nocor;
    dqdc[9] = q_nocor;
    dqdc[10] = 2 * q_nocor;
    dqdc[11] = 1.5 * q_nocor - k_r * sc[1];
    dqdc[12] = 2 * q_nocor;
    dqdc[13] = q_nocor + k_f;
    dqdc[14] = q_nocor;
    dqdc[15] = q_nocor;
    dqdc[16] = q_nocor;
    for (int k = 0; k < 17; k++) {
      J[18 * k + 1] += dqdc[k];
      J[18 * k + 11] += dqdc[k];
      J[18 * k + 13] -= dqdc[k];
    }
  }
  J[307] += dqdT; // dwdot[H]/dT
  J[317] += dqdT; // dwdot[CO]/dT
  J[319] -= dqdT; // dwdot[HCO]/dT

  // reaction 2: H2 + O <=> H + OH
  // a non-third-body and non-pressure-fall-off reaction
  // forward
  phi_f = sc[0] * sc[2];
  k_f = 0.05 * exp(2.67 * logT - (3165.23282791169) * invT);
  dlnkfdT = 2.67 * invT + (3165.23282791169) * invT2;
  // reverse
  phi_r = sc[1] * sc[4];
  Kc =
    (kc_fast ? (inv_ge[0] * ge[4] * inv_ge[2] * ge[1])
             : exp(g_RT[0] - g_RT[1] + g_RT[2] - g_RT[4]));
  k_r = k_f / Kc;
  dlnKcdT = invT * (-(h_RT[0] + h_RT[2]) + (h_RT[1] + h_RT[4]));
  dkrdT = (dlnkfdT - dlnKcdT) * k_r;
  // rate of progress
  q = k_f * phi_f - k_r * phi_r;
  dqdT = (dlnkfdT * k_f * phi_f - dkrdT * phi_r);
  // update wdot
  wdot[0] -= q; // H2
  wdot[1] += q; // H
  wdot[2] -= q; // O
  wdot[4] += q; // OH
  // d()/d[H2]
  dqdci = +k_f * sc[2];
  J[0] -= dqdci; // dwdot[H2]/d[H2]
  J[1] += dqdci; // dwdot[H]/d[H2]
  J[2] -= dqdci; // dwdot[O]/d[H2]
  J[4] += dqdci; // dwdot[OH]/d[H2]
